ROOT = Path(__file__).resolve().parent
MANIFEST: dict[str, Any] = json.loads((ROOT / "data" / "manifest.json").read_text("utf-8"))
NAME: str = MANIFEST["name"]
TITLE: str = MANIFEST["title"]
VERSION: str = MANIFEST["targetVersion"]
MAX_RESPONSE_CHARS = 50_000


def log(message: str) -> None:
    print(f"[{NAME}] {message}", file=sys.stderr, flush=True)


def text(value: str, is_error: bool = False) -> types.CallToolResult:
    return types.CallToolResult(content=[types.TextContent(type="text", text=value)], is_error=is_error)


# ---------------------------------------------------------------------------
# Docs
# ---------------------------------------------------------------------------


def corpus_cache_path() -> Path:
    """Same location the `make-mcp refresh` command writes to."""
    base = os.environ.get("MAKE_MCP_CACHE_DIR") or str(
        Path(os.environ.get("XDG_CACHE_HOME") or Path.home() / ".cache") / "make-mcp"
    )
    return Path(base) / NAME / VERSION / "corpus.json"


def load_pages() -> tuple[list[dict[str, Any]], str | None]:
    docs = MANIFEST.get("docs")
    if not docs:
        return [], None
    path = ROOT / "data" / "corpus.json" if docs["contentMode"] == "embedded" else corpus_cache_path()
    if not path.exists():
        return [], (
            f"Documentation has not been downloaded yet. Run `uv run server.py --refresh` in {ROOT} "
            "(fetches it from the original source on this machine)."
        )
    return json.loads(path.read_text("utf-8"))["pages"], None


PAGES, DOCS_ERROR = load_pages()
if DOCS_ERROR:
    log(DOCS_ERROR)
COMPONENTS = [p for p in PAGES if p["kind"] == "component"]
TOKEN = re.compile(r"[a-z0-9]+")


class SearchIndex:
    """Dependency-free BM25 over title, section and body with prefix matching (mirrors the TS server's MiniSearch)."""

    FIELDS = (("title", 4.0), ("section", 2.0), ("markdown", 1.0))
    K1, B = 1.2, 0.75

    def __init__(self, pages: list[dict[str, Any]]) -> None:
        self.pages = pages
        self.tf: list[dict[str, Counter[str]]] = []
        self.lengths: dict[str, list[int]] = {field: [] for field, _ in self.FIELDS}
        self.postings: dict[str, set[int]] = {}
        for i, page in enumerate(pages):
            counts = {field: Counter(TOKEN.findall(str(page.get(field) or "").lower())) for field, _ in self.FIELDS}
            self.tf.append(counts)
            for field, _ in self.FIELDS:
                self.lengths[field].append(sum(counts[field].values()))
                for term in counts[field]:
                    self.postings.setdefault(term, set()).add(i)
        self.average = {f: (sum(v) / len(v) if v else 0.0) or 1.0 for f, v in self.lengths.items()}
        self.vocabulary = sorted(self.postings)

    def _expand(self, term: str) -> list[tuple[str, float]]:
        expanded = [(term, 1.0)] if term in self.postings else []
        if len(term) >= 3:
            start = bisect.bisect_left(self.vocabulary, term)
            for candidate in self.vocabulary[start : start + 50]:
                if not candidate.startswith(term):
                    break
                if candidate != term:
                    expanded.append((candidate, 0.5))
        return expanded

    def search(self, query: str, limit: int, only: set[int] | None = None) -> list[dict[str, Any]]:
        scores: dict[int, float] = {}
        total = len(self.pages)
        for term in TOKEN.findall(query.lower()):
            for candidate, weight in self._expand(term):
                docs = self.postings[candidate]
                idf = math.log(1 + (total - len(docs) + 0.5) / (len(docs) + 0.5))
                for i in docs:
                    if only is not None and i not in only:
                        continue
                    score = 0.0
                    for field, boost in self.FIELDS:
                        tf = self.tf[i][field][candidate]
                        if tf:
                            norm = 1 - self.B + self.B * self.lengths[field][i] / self.average[field]
                            score += boost * tf * (self.K1 + 1) / (tf + self.K1 * norm)
                    scores[i] = scores.get(i, 0.0) + weight * idf * score
        ranked = sorted(scores.items(), key=lambda item: item[1], reverse=True)
        return [self.pages[i] for i, _ in ranked[:limit]]


INDEX = SearchIndex(PAGES)
COMPONENT_IDS = {i for i, p in enumerate(PAGES) if p["kind"] == "component"}


def search_pages(query: str, limit: int, only_components: bool = False) -> list[dict[str, Any]]:
    return INDEX.search(query, limit, COMPONENT_IDS if only_components else None)


def find_page(path: str) -> dict[str, Any] | None:
    wanted = re.sub(r"^docs://[^/]+/", "", path).lstrip("/")
    return next((p for p in PAGES if p["path"] == wanted), None)


def snippet(markdown: str, query: str) -> str:
    body = re.sub(r"^#+\s.*$", "", markdown, count=1, flags=re.M).strip()
    first = (TOKEN.findall(query.lower()) or [""])[0]
    start = max(0, body.lower().find(first) - 80)
    return ("…" if start else "") + re.sub(r"\s+", " ", body[start : start + 320]) + "…"


READ_ONLY = types.ToolAnnotations(read_only_hint=True, open_world_hint=False)
DOCS_TOOLS: list[types.Tool] = []
if MANIFEST.get("docs"):
    DOCS_TOOLS = [
        types.Tool(
            name="search_docs",
            description=f"Full-text search in the {TITLE} {VERSION} documentation. Returns matching pages with paths for get_page.",
            input_schema={
                "type": "object",
                "properties": {"query": {"type": "string"}, "limit": {"type": "number"}},
                "required": ["query"],
            },
            annotations=READ_ONLY,
        ),
        types.Tool(
            name="get_page",
            description=f"Returns the full Markdown of a {TITLE} documentation page by path.",
            input_schema={"type": "object", "properties": {"path": {"type": "string"}}, "required": ["path"]},
            annotations=READ_ONLY,
        ),
        types.Tool(
            name="list_topics",
            description=f"Lists all {TITLE} documentation pages grouped by section.",
            input_schema={"type": "object", "properties": {}},
            annotations=READ_ONLY,
        ),
    ]
    if COMPONENTS:
        names = ", ".join(c["title"] for c in COMPONENTS[:12])
        DOCS_TOOLS.append(
            types.Tool(
                name="get_component",
                description=f"Returns usage, class names and examples for a {TITLE} component ({names}{', …' if len(COMPONENTS) > 12 else ''}).",
                input_schema={"type": "object", "properties": {"name": {"type": "string"}}, "required": ["name"]},
                annotations=READ_ONLY,
            )
        )


def call_docs_tool(name: str, args: dict[str, Any]) -> types.CallToolResult | None:
    if not any(t.name == name for t in DOCS_TOOLS):
        return None
    if DOCS_ERROR:
        return text(DOCS_ERROR, True)
    if name == "search_docs":
        query = str(args.get("query", ""))
        hits = search_pages(query, min(int(args.get("limit") or 5), 20))
        if not hits:
            return text(f'No results for "{query}". Try list_topics.')
        return text(
            "\n\n".join(
                f"## {p['title']}{' (' + p['section'] + ')' if p.get('section') else ''}\npath: {p['path']}\n{snippet(p['markdown'], query)}"
                for p in hits
            )
        )
    if name == "get_page":
        page = find_page(str(args.get("path", "")))
        if not page:
            return text(f"Unknown path \"{args.get('path')}\". Use search_docs or list_topics.", True)
        return text(f"{page['markdown']}\n\n_Source: {page['sourceUrl']}_")
    if name == "list_topics":
        groups: dict[str, list[dict[str, Any]]] = {}
        for page in PAGES:
            groups.setdefault(page.get("section") or "General", []).append(page)
        return text(
            "\n\n".join(
                f"## {section}\n" + "\n".join(f"- {p['title']} — `{p['path']}`" for p in pages)
                for section, pages in groups.items()
            )
        )
    if name == "get_component":
        wanted = str(args.get("name", "")).lower().strip()
        for c in COMPONENTS:
            if c["title"].lower() == wanted or c["path"].split("/")[-1] == wanted.replace(" ", "-"):
                return text(f"{c['markdown']}\n\n_Source: {c['sourceUrl']}_")
        similar = [p["title"] for p in search_pages(wanted, 5, only_components=True)]
        hint = f" Did you mean: {', '.join(similar)}?" if similar else ""
        return text(f"No component named \"{args.get('name')}\".{hint}", True)
    return None


# ---------------------------------------------------------------------------
# API
# ---------------------------------------------------------------------------

API: dict[str, Any] | None = (
    json.loads((ROOT / "data" / "api.json").read_text("utf-8")) if MANIFEST.get("api") else None
)
ENDPOINTS: list[dict[str, Any]] = API["endpoints"] if API else []


def env(suffix: str) -> str | None:
    return os.environ.get(f"{MANIFEST['envPrefix']}_{suffix}")


def api_version() -> str | None:
    if not API or API["versionStrategy"]["type"] == "none":
        return None
    return env("API_VERSION") or API["versionStrategy"]["default"]


def base_url() -> str:
    return (env("BASE_URL") or API["baseUrl"]).replace("{apiVersion}", api_version() or "")  # type: ignore[index]


def tool_schema(ep: dict[str, Any]) -> dict[str, Any]:
    properties: dict[str, Any] = {}
    required: list[str] = []
    for p in ep["params"]:
        properties[p["name"]] = {**p["schema"], **({"description": p["description"]} if p.get("description") else {})}
        if p["required"]:
            required.append(p["name"])
    if ep.get("body"):
        properties["body"] = {**ep["body"]["schema"], "description": f"Request body ({ep['body']['contentType']})"}
        if ep["body"]["required"]:
            required.append("body")
    return {"type": "object", "properties": properties, **({"required": required} if required else {})}


API_TOOLS = [
    types.Tool(
        name=ep["id"],
        description="\n\n".join(
            s for s in [ep.get("summary"), ep.get("description"), f"{ep['method'].upper()} {ep['path']}"] if s
        )[:1024],
        input_schema=tool_schema(ep),
        annotations=types.ToolAnnotations(
            read_only_hint=ep["method"] in ("get", "head"),
            destructive_hint=ep["method"] == "delete",
            idempotent_hint=ep["method"] in ("get", "head", "put", "delete"),
            open_world_hint=True,
        ),
    )
    for ep in ENDPOINTS
]

# Large APIs: three meta tools instead of one tool per operation keep the client's context small.
GROUPED = MANIFEST.get("toolMode") == "grouped"
ENDPOINT_BY_ID = {ep["id"]: ep for ep in ENDPOINTS}

GROUPED_TOOLS = [
    types.Tool(
        name="list_operations",
        description=f"List {API['title'] if API else 'API'} operations (id, method, path, summary). "
        "Filter by tag and/or keyword, then use describe_operation.",
        input_schema={
            "type": "object",
            "properties": {
                "tag": {"type": "string", "description": "Only operations with this tag"},
                "query": {"type": "string", "description": "Keyword matched against id, path and summary"},
            },
        },
        annotations=types.ToolAnnotations(read_only_hint=True, open_world_hint=False),
    ),
    types.Tool(
        name="describe_operation",
        description="Parameters, request body schema and description of one operation.",
        input_schema={
            "type": "object",
            "properties": {"operation": {"type": "string", "description": "Operation id from list_operations"}},
            "required": ["operation"],
        },
        annotations=types.ToolAnnotations(read_only_hint=True, open_world_hint=False),
    ),
    types.Tool(
        name="call_operation",
        description="Call an operation against the live API. Arguments follow the schema returned by describe_operation.",
        input_schema={
            "type": "object",
            "properties": {
                "operation": {"type": "string", "description": "Operation id from list_operations"},
                "arguments": {
                    "type": "object",
                    "description": "Path, query and header parameters by name, plus `body` for the request body",
                },
            },
            "required": ["operation"],
        },
        annotations=types.ToolAnnotations(
            read_only_hint=False,
            destructive_hint=any(ep["method"] == "delete" for ep in ENDPOINTS),
            open_world_hint=True,
        ),
    ),
]


def list_operations(args: dict[str, Any]) -> types.CallToolResult:
    tag = str(args["tag"]).lower() if args.get("tag") else None
    query = str(args["query"]).lower() if args.get("query") else None
    matches = [
        ep
        for ep in ENDPOINTS
        if (not tag or any(t.lower() == tag for t in ep["tags"]))
        and (not query or any(query in (s or "").lower() for s in (ep["id"], ep["path"], ep.get("summary"))))
    ]
    if not matches:
        tags = sorted({t for ep in ENDPOINTS for t in ep["tags"]})
        return text(f"No operations match. Tags: {', '.join(tags) or 'none'}")
    lines = [
        f"{ep['id']} – {ep['method'].upper()} {ep['path']}"
        + (f" – {ep['summary']}" if ep.get("summary") else "")
        + (" (deprecated)" if ep["deprecated"] else "")
        for ep in matches[:200]
    ]
    if len(matches) > len(lines):
        lines.append(f"… {len(matches) - len(lines)} more, narrow with tag or query")
    return text("\n".join(lines))


def describe_operation(operation: Any) -> types.CallToolResult:
    ep = ENDPOINT_BY_ID.get(str(operation))
    if not ep:
        return text(f"Unknown operation: {operation}. Use list_operations.", True)
    detail = {
        "operation": ep["id"],
        "request": f"{ep['method'].upper()} {ep['path']}",
        "summary": ep.get("summary"),
        "description": ep.get("description"),
        "tags": ep["tags"],
        **({"deprecated": True} if ep["deprecated"] else {}),
        "arguments": tool_schema(ep),
    }
    return text(json.dumps({k: v for k, v in detail.items() if v is not None}, indent=2))


_oauth: dict[str, Any] = {}


async def authorize(client: httpx.AsyncClient, headers: dict[str, str], params: dict[str, Any]) -> None:
    for scheme in API["auth"] if API else []:
        kind = scheme["type"]
        if kind == "apiKey" and os.environ.get(scheme["envVar"]):
            value = os.environ[scheme["envVar"]]
            if scheme["in"] == "header":
                headers[scheme["name"]] = value
            elif scheme["in"] == "query":
                params[scheme["name"]] = value
            else:
                headers["cookie"] = f"{scheme['name']}={quote(value)}"
            return
        if kind == "bearer" and os.environ.get(scheme["envVar"]):
            headers["authorization"] = f"Bearer {os.environ[scheme['envVar']]}"
            return
        if kind == "basic" and os.environ.get(scheme["userEnvVar"]):
            raw = f"{os.environ[scheme['userEnvVar']]}:{os.environ.get(scheme['passwordEnvVar'], '')}"
            headers["authorization"] = "Basic " + base64.b64encode(raw.encode()).decode()
            return
        if kind == "oauth2":
            if os.environ.get(scheme["tokenEnvVar"]):
                headers["authorization"] = f"Bearer {os.environ[scheme['tokenEnvVar']]}"
                return
            client_id = os.environ.get(scheme["clientIdEnvVar"])
            if scheme.get("tokenUrl") and client_id:
                if not _oauth or _oauth["expires_at"] < time.time() + 30:
                    res = await client.post(
                        scheme["tokenUrl"],
                        data={
                            "grant_type": "client_credentials",
                            "client_id": client_id,
                            "client_secret": os.environ.get(scheme["clientSecretEnvVar"], ""),
                            **({"scope": " ".join(scheme["scopes"])} if scheme["scopes"] else {}),
                        },
                    )
                    res.raise_for_status()
                    token = res.json()
                    _oauth.update(value=token["access_token"], expires_at=time.time() + token.get("expires_in", 3600))
                headers["authorization"] = f"Bearer {_oauth['value']}"
                return


async def call_endpoint(ep: dict[str, Any], args: dict[str, Any]) -> types.CallToolResult:
    path = re.sub(r"\{([^}]+)\}", lambda m: quote(str(args.get(m.group(1), "")), safe=""), ep["path"])
    url = base_url().rstrip("/") + path
    headers: dict[str, str] = {"accept": "application/json, text/plain;q=0.9, */*;q=0.5"}
    params: dict[str, Any] = {}
    strategy = API["versionStrategy"]  # type: ignore[index]
    if strategy["type"] == "header":
        headers[strategy["name"]] = api_version() or ""
    elif strategy["type"] == "query":
        params[strategy["name"]] = api_version()

    for p in ep["params"]:
        value = args.get(p["name"])
        if value is None or p["in"] == "path":
            continue
        serialized = value if isinstance(value, str) else json.dumps(value)
        if p["in"] == "query":
            params[p["name"]] = value if isinstance(value, list) else serialized
        elif p["in"] == "header":
            headers[p["name"]] = serialized
        else:
            headers["cookie"] = f"{headers.get('cookie', '')}; {p['name']}={quote(serialized)}".lstrip("; ")

    async with httpx.AsyncClient(timeout=30) as client:
        await authorize(client, headers, params)
        kwargs: dict[str, Any] = {}
        body = ep.get("body")
        if body and args.get("body") is not None:
            if "json" in body["contentType"]:
                kwargs["json"] = args["body"]
            elif "multipart" in body["contentType"]:
                kwargs["files"] = {k: (None, v if isinstance(v, str) else json.dumps(v)) for k, v in args["body"].items()}
            else:
                kwargs["data"] = args["body"]
        res = await client.request(ep["method"].upper(), url, headers=headers, params=params, **kwargs)

    payload = res.text
    if "json" in res.headers.get("content-type", ""):
        try:
            payload = json.dumps(res.json(), indent=2)
        except ValueError:
            pass
    if len(payload) > MAX_RESPONSE_CHARS:
        payload = payload[:MAX_RESPONSE_CHARS] + "\n… (truncated)"
    return text(f"HTTP {res.status_code} {res.reason_phrase}\n\n{payload}", res.is_error)


RESOURCE_ENDPOINTS = [ep for ep in ENDPOINTS if ep["resource"]]


def api_uri(path: str) -> str:
    return f"api://{NAME}{path}"


def match_resource(uri: str) -> tuple[dict[str, Any], dict[str, str]] | None:
    for ep in RESOURCE_ENDPOINTS:
        names = re.findall(r"\{([^}]+)\}", ep["path"])
        pattern = "^" + re.sub(r"\\\{[^}]+\\\}", "([^/]+)", re.escape(api_uri(ep["path"]))) + "$"
        match = re.match(pattern, uri)
        if match:
            return ep, {n: unquote(v) for n, v in zip(names, match.groups())}
    return None


# ---------------------------------------------------------------------------
# MCP wiring
# ---------------------------------------------------------------------------


async def on_list_tools(_ctx: Any, _params: Any) -> types.ListToolsResult:
    return types.ListToolsResult(tools=[*DOCS_TOOLS, *(GROUPED_TOOLS if GROUPED else API_TOOLS)])


async def on_call_tool(_ctx: Any, params: types.CallToolRequestParams) -> types.CallToolResult:
    args = params.arguments or {}
    result = call_docs_tool(params.name, args)
    if result:
        return result
    if GROUPED and params.name == "list_operations":
        return list_operations(args)
    if GROUPED and params.name == "describe_operation":
        return describe_operation(args.get("operation"))
    if GROUPED:
        if params.name != "call_operation":
            return text(f"Unknown tool: {params.name}", True)
        ep = ENDPOINT_BY_ID.get(str(args.get("operation")))
        if not ep:
            return text(f"Unknown operation: {args.get('operation')}. Use list_operations.", True)
        args = args.get("arguments") or {}
    else:
        ep = ENDPOINT_BY_ID.get(params.name)
        if not ep:
            return text(f"Unknown tool: {params.name}", True)
    try:
        return await call_endpoint(ep, args)
    except Exception as err:  # noqa: BLE001 – surface any transport error to the client
        return text(f"Request failed: {err}", True)


async def on_list_resources(_ctx: Any, _params: Any) -> types.ListResourcesResult:
    resources = [
        types.Resource(name=p["title"], uri=f"docs://{NAME}/{p['path']}", mime_type="text/markdown") for p in PAGES[:500]
    ]
    resources += [
        types.Resource(name=ep.get("summary") or ep["id"], uri=api_uri(ep["path"]), mime_type="application/json")
        for ep in RESOURCE_ENDPOINTS
        if "{" not in ep["path"]
    ]
    return types.ListResourcesResult(resources=resources)


async def on_list_resource_templates(_ctx: Any, _params: Any) -> types.ListResourceTemplatesResult:
    templates = [
        types.ResourceTemplate(name=ep.get("summary") or ep["id"], uri_template=api_uri(ep["path"]), mime_type="application/json")
        for ep in RESOURCE_ENDPOINTS
        if "{" in ep["path"]
    ]
    if MANIFEST.get("docs"):
        templates.append(
            types.ResourceTemplate(name="Documentation page", uri_template=f"docs://{NAME}/{{path}}", mime_type="text/markdown")
        )
    return types.ListResourceTemplatesResult(resource_templates=templates)


async def on_read_resource(_ctx: Any, params: types.ReadResourceRequestParams) -> types.ReadResourceResult:
    uri = str(params.uri)
    if uri.startswith(f"docs://{NAME}/"):
        page = find_page(uri)
        if not page:
            raise ValueError(f"Unknown resource {uri}")
        return types.ReadResourceResult(
            contents=[types.TextResourceContents(uri=uri, mime_type="text/markdown", text=page["markdown"])]
        )
    match = match_resource(uri)
    if not match:
        raise ValueError(f"Unknown resource {uri}")
    result = await call_endpoint(*match)
    content = result.content[0].text if result.content else ""  # type: ignore[union-attr]
    return types.ReadResourceResult(contents=[types.TextResourceContents(uri=uri, mime_type="application/json", text=content)])


INSTRUCTIONS = " ".join(
    s
    for s in [
        f"Documentation for {TITLE} {VERSION}: use search_docs first, then get_page." if MANIFEST.get("docs") else "",
        (
            f"{API['title']} API ({len(ENDPOINTS)} operations): list_operations → describe_operation → call_operation."
            if GROUPED
            else f"{API['title']} API ({len(ENDPOINTS)} operations). Tools call the live API."
        )
        if API
        else "",
    ]
    if s
)


def create_server() -> Server:
    return Server(
        NAME,
        version=VERSION,
        instructions=INSTRUCTIONS,
        on_list_tools=on_list_tools,
        on_call_tool=on_call_tool,
        on_list_resources=on_list_resources,
        on_list_resource_templates=on_list_resource_templates,
        on_read_resource=on_read_resource,
    )


async def run_stdio() -> None:
    from mcp.server.stdio import stdio_server

    server = create_server()
    async with stdio_server() as (read, write):
        await server.run(read, write, server.create_initialization_options())


def run_http(legacy_sse: bool) -> None:
    import contextlib

    import uvicorn
    from mcp.server.sse import SseServerTransport
    from mcp.server.streamable_http_manager import StreamableHTTPSessionManager
    from starlette.applications import Starlette
    from starlette.responses import PlainTextResponse, Response
    from starlette.routing import Mount, Route

    host, port = os.environ.get("HOST", "127.0.0.1"), int(os.environ.get("PORT", "3000"))
    token = os.environ.get("MCP_AUTH_TOKEN")
    if host not in ("127.0.0.1", "localhost", "::1") and not token and os.environ.get("MCP_ALLOW_UNAUTHENTICATED") != "1":
        log(
            f"Refusing to listen on {host} without MCP_AUTH_TOKEN. "
            "Set MCP_ALLOW_UNAUTHENTICATED=1 if access is controlled elsewhere (e.g. Cloud Run IAM)."
        )
        sys.exit(1)
    manager = StreamableHTTPSessionManager(app=create_server(), stateless=True)

    def authorized(scope: Any) -> bool:
        auth = dict(scope.get("headers") or []).get(b"authorization", b"").decode()
        return not token or auth == f"Bearer {token}"

    class Guarded:
        """ASGI app that checks MCP_AUTH_TOKEN (a class, so Starlette routes it as a raw ASGI app)."""

        def __init__(self, app: Any) -> None:
            self.app = app

        async def __call__(self, scope: Any, receive: Any, send: Any) -> None:
            if not authorized(scope):
                await PlainTextResponse("unauthorized", status_code=401)(scope, receive, send)
                return
            await self.app(scope, receive, send)

    routes: list[Any] = [Route("/healthz", lambda _r: PlainTextResponse("ok")), Mount("/mcp", app=Guarded(manager.handle_request))]
    if legacy_sse:
        sse = SseServerTransport("/messages/")

        async def handle_sse(scope: Any, receive: Any, send: Any) -> None:
            server = create_server()
            async with sse.connect_sse(scope, receive, send) as (read, write):
                await server.run(read, write, server.create_initialization_options())
            await Response()(scope, receive, send)

        routes += [Route("/sse", Guarded(handle_sse), methods=["GET"]), Mount("/messages/", app=Guarded(sse.handle_post_message))]

    @contextlib.asynccontextmanager
    async def lifespan(_app: Starlette):  # type: ignore[no-untyped-def]
        async with manager.run():
            yield

    log(f"listening on http://{host}:{port}/mcp" + (" (legacy SSE on /sse)" if legacy_sse else ""))
    uvicorn.run(Starlette(routes=routes, lifespan=lifespan), host=host, port=port, log_level="warning")


def refresh() -> int:
    """Downloads documentation for servers that must not embed it (see README) into the local cache."""
    docs = MANIFEST.get("docs")
    if not docs or docs["contentMode"] == "embedded":
        print("Nothing to refresh: the documentation is embedded in this server.", file=sys.stderr)
        return 0
    npx = shutil.which("npx")
    if not npx:
        print(
            "Downloading the documentation uses the make-mcp CLI and needs Node.js ≥ 22 (npx). "
            f"Install Node.js, then run: npx -y {MANIFEST['generator']} refresh {ROOT}",
            file=sys.stderr,
        )
        return 1
    return subprocess.call([npx, "-y", MANIFEST["generator"], "refresh", str(ROOT)])


if __name__ == "__main__":
    if "--refresh" in sys.argv[1:]:
        sys.exit(refresh())
    transport = os.environ.get("MCP_TRANSPORT") or MANIFEST["transport"]
    if transport in ("http", "sse"):
        run_http(legacy_sse=transport == "sse")
    else:
        anyio.run(run_stdio)
